package dao;
import config.ConexionBD;import java.sql.*;import negocio.*;
public class EventoPagoDAOMySQL implements EventoPagoDAO { public boolean registrarSiNuevo(EventoPago e){String q="INSERT IGNORE INTO eventos_pago(orden_pago_id,proveedor,evento_externo_id,tipo,estado_procesamiento,firma_valida,payload_hash,payload_json,fecha_evento) VALUES(?,?,?,?,?,?,?,?,?)";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){if(e.getOrdenPagoId()>0)s.setLong(1,e.getOrdenPagoId());else s.setNull(1,Types.BIGINT);s.setString(2,e.getProveedor().name());s.setString(3,e.getEventoExternoId());s.setString(4,e.getTipo());s.setString(5,e.getEstadoProcesamiento().name());s.setBoolean(6,e.isFirmaValida());s.setString(7,e.getPayloadHash());if(e.getPayloadJson()==null)s.setNull(8,Types.VARCHAR);else s.setString(8,e.getPayloadJson());if(e.getFechaEvento()==null)s.setNull(9,Types.TIMESTAMP);else s.setTimestamp(9,Timestamp.valueOf(e.getFechaEvento()));boolean nuevo=s.executeUpdate()==1;if(nuevo)try(ResultSet r=s.getGeneratedKeys()){if(r.next())e.setId(r.getLong(1));}return nuevo;}catch(SQLException x){throw new RuntimeException("No se pudo registrar el evento.",x);}}public EventoPago buscar(String p,String id){String q="SELECT * FROM eventos_pago WHERE proveedor=? AND evento_externo_id=?";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q)){s.setString(1,p);s.setString(2,id);try(ResultSet r=s.executeQuery()){if(!r.next())return null;EventoPago e=new EventoPago();e.setId(r.getLong("id"));e.setOrdenPagoId(r.getLong("orden_pago_id"));e.setProveedor(ProveedorPago.valueOf(r.getString("proveedor")));e.setEventoExternoId(r.getString("evento_externo_id"));e.setTipo(r.getString("tipo"));e.setEstadoProcesamiento(EstadoProcesamientoEventoPago.valueOf(r.getString("estado_procesamiento")));e.setFirmaValida(r.getBoolean("firma_valida"));e.setPayloadHash(r.getString("payload_hash"));e.setPayloadJson(r.getString("payload_json"));e.setDetalleResultado(r.getString("detalle_resultado"));return e;}}catch(SQLException x){throw new RuntimeException("No se pudo buscar el evento.",x);}}public void marcarProcesado(long id,String d){estado(id,"PROCESADO",d);}public void marcarError(long id,String d){estado(id,"ERROR",d);}private void estado(long id,String e,String d){try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement("UPDATE eventos_pago SET estado_procesamiento=?,detalle_resultado=?,fecha_procesamiento=CURRENT_TIMESTAMP WHERE id=?")){s.setString(1,e);s.setString(2,d);s.setLong(3,id);s.executeUpdate();}catch(SQLException x){throw new RuntimeException("No se pudo actualizar el evento.",x);}}}
